'use strict';

/**
* Multiply two 64-bit signed integers.
*
* @module @stdlib/number/int64/base/mul
*
* @example
* var Int64 = require( '@stdlib/number/int64/ctor' );
* var mul = require( '@stdlib/number/int64/base/mul' );
*
* var a = new Int64( 5 );
* var b = new Int64( 10 );
*
* var v = mul( a, b );
* // returns <Int64>
*
* @example
* var Uint32Array = require( '@stdlib/array/uint32' );
* var mul = require( '@stdlib/number/int64/base/mul' );
*
* var out = new Uint32Array( 2 );
* var v = mul.assign( 1, 2, 3, 4, out, 1, 0 );
* // returns <Uint32Array>[ 10, 8 ]
*
* @example
* var Uint32Array = require( '@stdlib/array/uint32' );
* var mul = require( '@stdlib/number/int64/base/mul' );
*
* var a = new Uint32Array( [ 1, 2 ] );
* var b = new Uint32Array( [ 3, 4 ] );
* var out = new Uint32Array( 2 );
*
* var v = mul.strided( a, 1, 0, b, 1, 0, out, 1, 0 );
* // returns <Uint32Array>[ 10, 8 ]
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var main = require( './main.js' );
var assign = require( './assign.js' );
var strided = require( './strided.js' );


// MAIN //

setReadOnly( main, 'assign', assign );
setReadOnly( main, 'strided', strided );


// EXPORTS //

module.exports = main;
